import axios from "axios";

const cache = {};

// ✅ BASE URL FIX (NO FALLBACK ISSUE)
const baseURL =
  window.location.hostname === "localhost" || window.location.hostname === "127.0.0.1"
    ? "http://127.0.0.1:8000"
    : process.env.REACT_APP_API_URL || "http://127.0.0.1:8000";

// ❗ IMPORTANT: fallback गलत था → remove hardcoded tunnel

const api = axios.create({
  baseURL,
  timeout: 8000,
  headers: {
    "Content-Type": "application/json",
  },
});

// 🔑 CACHE KEY
const getCacheKey = (url, config = {}) => {
  const params = config.params ? JSON.stringify(config.params) : "";
  return `${url}?${params}`;
};

// 🔐 REQUEST INTERCEPTOR (TOKEN FIX)
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");

  if (token && token !== "null" && token !== "undefined") {
    config.headers.Authorization = `Bearer ${token}`;
  } else {
    delete config.headers.Authorization;
  }

  return config;
});

// 📦 RESPONSE INTERCEPTOR
api.interceptors.response.use(
  (response) => {
    const method = response.config?.method?.toLowerCase();
    const url = response.config?.url;

    // ✅ CACHE ONLY GET
    if (method === "get" && url) {
      const key = getCacheKey(url, response.config);
      cache[key] = {
        data: response.data,
        time: Date.now(),
      };
    }

    // ❌ CLEAR CACHE ON WRITE
    if (["post", "put", "delete", "patch"].includes(method)) {
      Object.keys(cache).forEach((key) => delete cache[key]);
    }

    return response;
  },

  async (error) => {
    const config = error.config;

    // 🚨 401 FIX (MOST IMPORTANT)
    if (error.response?.status === 401) {
      console.log("Unauthorized → logging out");

      localStorage.removeItem("token");

      // redirect to login
      window.location.href = "/login";

      return Promise.reject(error);
    }

    // ❌ RETRY ONLY NETWORK ERRORS
    if (!config || config.__retry) {
      return Promise.reject(error);
    }

    if (!error.response) {
      config.__retry = true;
      return api(config);
    }

    return Promise.reject(error);
  }
);

// 💾 GET WITH CACHE
const axiosGet = api.get.bind(api);

api.get = async (url, config = {}) => {
  const cacheKey = getCacheKey(url, config);
  const cached = cache[cacheKey];

  const CACHE_TIME = 5000;

  if (
    config.cache !== false &&
    cached &&
    Date.now() - cached.time < CACHE_TIME
  ) {
    return {
      data: cached.data,
      status: 200,
      statusText: "OK",
      headers: {},
      config,
    };
  }

  const response = await axiosGet(url, config);

  cache[cacheKey] = {
    data: response.data,
    time: Date.now(),
  };

  return response;
};

// 🧹 CLEAR CACHE
api.clearCache = (keys = []) => {
  if (!keys.length) {
    Object.keys(cache).forEach((key) => delete cache[key]);
    return;
  }

  keys.forEach((key) => {
    Object.keys(cache)
      .filter((cacheKey) => cacheKey.startsWith(key))
      .forEach((cacheKey) => delete cache[cacheKey]);
  });
};

export default api;
